void rde_group_list_remove ( struct iface * iface , struct in_addr group ) { struct rde_group * rg ; struct rt_node * rn ; if ( TAILQ_EMPTY ( & iface -> rde_group_list ) ) { fatalx ( "rde_group_list_remove: group does not exist" ) ; } for ( rg = TAILQ_FIRST ( & iface -> rde_group_list ) ; rg != NULL ; rg = TAILQ_NEXT ( rg , entry ) ) { if ( rg -> rde_group . s_addr == group . s_addr ) { log_debug ( "group_list_remove: interface %s, group %s" , iface -> name , inet_ntoa ( rg -> rde_group ) ) ; TAILQ_REMOVE ( & iface -> rde_group_list , rg , entry ) ; free ( rg ) ; } } rn = mfc_find_origin ( group ) ; if ( rn == NULL ) { return ; } } 